if (count < RequiredPlayers)
{
    Countdown = TickTimer.None;
    return;
}
if (!Countdown.IsRunning)
    Countdown = TickTimer.CreateFromSeconds(Runner, DelaySeconds);
if (count == Runner.SessionInfo.MaxPlayers && RemainingCountdownSeconds() > FullRoomDelaySeconds)
    Countdown = TickTimer.CreateFromSeconds(Runner, FullRoomDelaySeconds);
if (Countdown.Expired(Runner) && Runner.IsSceneAuthority) StartGame();

private void OnSelectEntered(SelectEnterEventArgs args)
{
    if (!Object || !Object.IsValid || Runner.LocalPlayer == PlayerRef.None) return;
    // In Shared mode, request ownership so this client can synchronize the cube.
    if (!Object.HasStateAuthority) Object.RequestStateAuthority();
}

private void OnSelectExited(SelectExitEventArgs args)
{
    if (_grab.isSelected || !Object || !Object.IsValid) return;
    // Relinquish ownership when the last local hand releases the cube.
    if (Object.HasStateAuthority) Object.ReleaseStateAuthority();
}

[Rpc(RpcSources.All, RpcTargets.All)]
private void RpcSetColor(Color color)
{
    if (targetRenderer) targetRenderer.material.color = color;
    if (txtInfo) txtInfo.text = color.Equals(_originalColor) ? "Tap the cube!" : "";
}

[Rpc(RpcSources.All, RpcTargets.StateAuthority)]
private void RpcRequestColor(Color requestedColor, RpcInfo info = default)
{
    // In this exercise, only the player who owns the held cube may recolor it.
    if (info.Source != Object.StateAuthority) return;
    CubeColor = requestedColor; // Persistent replicated state.
    RpcCelebrate();            // A one-time effect for current peers.
}

[Rpc(RpcSources.StateAuthority, RpcTargets.All)]
private void RpcCelebrate()
{
    if (celebration) celebration.Play();
}
